<script setup>
import { computed, reactive, ref, watch } from 'vue'; import { Plus, Search, TrendingUp } from 'lucide-vue-next'; import { useAuthStore } from '@/stores/auth'; import { useFinanceStore } from '@/stores/finance'; import { masterDataConfig } from '@/data/masterDataMock'; import { formatCurrency, formatDate } from '@/utils/formatters'; import BaseBadge from '@/components/ui/BaseBadge.vue'; import BaseButton from '@/components/ui/BaseButton.vue'; import BaseCard from '@/components/ui/BaseCard.vue'; import BaseInput from '@/components/ui/BaseInput.vue'; import BaseModal from '@/components/ui/BaseModal.vue'; import BaseSelect from '@/components/ui/BaseSelect.vue'; import BaseTextarea from '@/components/ui/BaseTextarea.vue'; import Pagination from '@/components/ui/Pagination.vue'; import { useUiStore } from '@/stores/ui';
const finance=useFinanceStore(),auth=useAuthStore(),ui=useUiStore(),search=ref(''),period=ref('semua'),category=ref('semua'),account=ref('semua'),page=ref(1),modal=ref(false),edit=ref(null),error=ref(''),pageSize=5;const accounts=masterDataConfig.account.records.filter(x=>x.status==='aktif');const form=reactive({date:'2026-08-28',source:'Lain-lain',category:'',description:'',accountId:'r1',amount:'',notes:''});const readOnly=computed(()=>auth.role==='manager');const filtered=computed(()=>finance.allIncomes.filter(x=>`${x.description} ${x.invoiceNumber} ${x.client} ${x.source}`.toLowerCase().includes(search.value.toLowerCase())&&(period.value==='semua'||x.date.slice(0,7)==='2026-08')&&(category.value==='semua'||x.category===category.value)&&(account.value==='semua'||x.accountId===account.value)));const rows=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize));const total=computed(()=>filtered.value.reduce((sum,x)=>sum+x.amount,0));watch([search,period,category,account],()=>page.value=1);const accountName=id=>accounts.find(x=>x.id===id)?.nama||'-';const openAdd=()=>{edit.value=null;Object.assign(form,{date:'2026-08-28',source:'Lain-lain',category:'',description:'',accountId:'r1',amount:'',notes:''});error.value='';modal.value=true};const openEdit=item=>{edit.value=item;Object.assign(form,item,{amount:String(item.amount)});error.value='';modal.value=true};const save=()=>{try{if(edit.value)finance.updateManualIncome(edit.value.id,form);else finance.addManualIncome(form);ui.notify(edit.value?'Pemasukan berhasil diperbarui.':'Pemasukan berhasil ditambahkan.');modal.value=false}catch(e){error.value=e.message}};
</script>
<template><div class="p-6"><header class="mb-5 flex items-start justify-between"><div><h1 class="text-xl font-semibold text-[#172033]">Pemasukan</h1><p class="mt-0.5 text-sm text-[#667085]">Pencatatan seluruh penerimaan kas dan bank perusahaan.</p></div><BaseButton v-if="!readOnly" @click="openAdd"><Plus :size="15"/>Tambah Pemasukan</BaseButton></header><BaseCard class="mb-5 flex items-center justify-between" padding="p-4"><div><p class="text-xs text-[#667085]">Total Pemasukan</p><p class="text-2xl font-bold text-[#16A34A]">{{formatCurrency(total)}}</p></div><TrendingUp :size="32" class="text-green-200"/></BaseCard><div class="mb-4 flex flex-wrap items-center gap-3"><BaseInput v-model="search" class="max-w-xs flex-1" placeholder="Cari pemasukan..."><template #prefix><Search :size="14"/></template></BaseInput><BaseSelect v-model="period" class="w-36" :options="[{value:'semua',label:'Semua Periode'},{value:'bulan_ini',label:'Bulan Ini'}]"/><BaseSelect v-model="category" class="w-40" :options="[{value:'semua',label:'Semua Kategori'},'Pendapatan Jasa','Pendapatan Lainnya']"/><BaseSelect v-model="account" class="w-36" :options="[{value:'semua',label:'Semua Rekening'},...accounts.map(x=>({value:x.id,label:x.nama}))]"/></div><section class="overflow-x-auto rounded-lg border border-[#E2E6EC] bg-white"><table class="w-full min-w-[1050px]"><thead><tr class="border-b border-[#E2E6EC] bg-[#F9FAFB]"><th v-for="h in ['Tanggal','Sumber','Kategori','Keterangan','Ref. Invoice','Rekening','Nominal','Aksi']" :key="h" class="px-4 py-3 text-left text-xs font-medium text-[#667085] first:px-5 last:text-center">{{h}}</th></tr></thead><tbody><tr v-for="income in rows" :key="income.id" class="border-b border-[#F3F4F6] hover:bg-gray-50"><td class="px-5 py-3.5 text-sm text-[#667085]">{{formatDate(income.date)}}</td><td class="px-4 py-3.5"><BaseBadge :variant="income.source==='invoice'?'info':'default'">{{income.source==='invoice'?'Invoice':'Manual'}}</BaseBadge></td><td class="px-4 py-3.5 text-sm text-[#667085]">{{income.category}}</td><td class="px-4 py-3.5 text-sm">{{income.description}}</td><td class="px-4 py-3.5 text-sm text-[#315DA8]">{{income.invoiceNumber||'-'}}</td><td class="px-4 py-3.5 text-sm text-[#667085]">{{accountName(income.accountId)}}</td><td class="px-4 py-3.5 text-right text-sm font-semibold text-green-600">{{formatCurrency(income.amount)}}</td><td class="px-4 py-3.5 text-center"><button v-if="income.source==='manual'&&!readOnly" class="text-xs text-[#315DA8] hover:underline" @click="openEdit(income)">Edit</button></td></tr></tbody></table><Pagination :page="page" :total="filtered.length" :per-page="pageSize" @change="page=$event"/></section><BaseModal :open="modal" :title="edit?'Edit Pemasukan Manual':'Tambah Pemasukan Manual'" size="md" @close="modal=false"><div class="space-y-4"><p class="rounded-md border border-amber-200 bg-amber-50 p-3 text-xs text-amber-700">Form ini untuk pemasukan non-invoice. Pembayaran invoice tercatat otomatis melalui Catat Pembayaran.</p><div class="grid gap-4 sm:grid-cols-2"><BaseInput v-model="form.date" label="Tanggal" type="date" required/><BaseInput v-model="form.amount" label="Nominal (Rp)" type="number" required/></div><BaseInput v-model="form.source" label="Sumber"/><BaseInput v-model="form.category" label="Kategori" required/><BaseSelect v-model="form.accountId" label="Rekening" :options="accounts.map(x=>({value:x.id,label:`${x.nama} — ${x.nomor}`}))"/><BaseTextarea v-model="form.description" label="Keterangan" required/><BaseTextarea v-model="form.notes" label="Catatan"/><p v-if="error" class="text-sm text-red-600">{{error}}</p></div><template #footer><BaseButton variant="secondary" @click="modal=false">Batal</BaseButton><BaseButton @click="save">Simpan</BaseButton></template></BaseModal></div></template>
